using System.Diagnostics; namespace CubeAntivirus.Modules; public sealed class TerminalManager { public async Task<string> ExecuteAsync(string command, CancellationToken token = default) { if (string.IsNullOrWhiteSpace(command)) return ""; var info = new ProcessStartInfo("cmd.exe") { Arguments = "/d /s /c " + command, UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true, CreateNoWindow = true }; using var process = new Process { StartInfo = info }; process.Start(); var stdout = process.StandardOutput.ReadToEndAsync(token); var stderr = process.StandardError.ReadToEndAsync(token); await process.WaitForExitAsync(token); return await stdout + await stderr; } }